function renderTray(){const t=$('tray');const list=ST.cmp;const cols=list.map(f=>esc(cname[f])).concat(['Texas']);
  t.innerHTML=`<div class="th" id="tray-h"><b>Compare</b>${list.map(f=>`<span class="chip">${esc(cname[f])}<i data-rm="${f}" title="Remove">✕</i></span>`).join('')}<span class="hint">${list.length?'':'Add up to three counties from a county page.'}${ST.f&&!list.includes(ST.f)&&list.length<3?` <button type="button" data-add="${ST.f}" style="font:600 12px IBM Plex Sans,sans-serif;padding:3px 8px;border-radius:999px;border:1px solid var(--rule);background:var(--paper2);cursor:pointer">+ Add ${esc(cname[ST.f])}</button>`:''}</span><span class="chev">${t.classList.contains('closed')?'▴':'▾'}</span></div>
    <div class="tbody">${list.length?`<table><tr><th>Metric</th>${cols.map(c=>`<th>${c}</th>`).join('')}</tr>${ROWS.map(([lab,fn,fmt])=>`<tr><td>${lab}</td>${list.concat(['48']).map(f=>{const v=fn(f);return `<td>${v==null||v===''||(typeof v==='number'&&isNaN(v))?'—':fmt(v)}</td>`;}).join('')}</tr>`).join('')}</table>`:'<div class="ccnote">Open a county and press "Add to compare"; two or three counties appear here side by side, always next to Texas.</div>'}</div>`;}
$('tray').addEventListener('click',ev=>{const rm=ev.target.closest('[data-rm]');if(rm){ST.cmp=ST.cmp.filter(f=>f!==rm.dataset.rm);saveCmp();renderTray();renderPanel();setHash();return;}
  const ad=ev.target.closest('[data-add]');if(ad){addCompare(ad.dataset.add);return;}
  if(ev.target.closest('#tray-h')){$('tray').classList.toggle('closed');renderTray();}});
function addCompare(f){if(!ST.cmp.includes(f)&&ST.cmp.length<3){ST.cmp.push(f);saveCmp();}$('tray').classList.remove('closed');renderTray();renderPanel();setHash();}
// keep the map legend just above the compare tray: main gets --tray-h = the tray's current height (see tx_deep_dive.css)
// ---- statements: What to know ----
function know(f){const c=E.counties[f]||{},v=V[f]||{};const out=[];const st=(t,ev)=>out.push({t,ev});
  if(c.registered_march_2026!=null&&c.registered_2024)st(`Voter registration ${c.registered_march_2026>=c.registered_2024?'grew':'fell'} since the 2024 election`,[['Nov. 2022',num(c.registered_2022)],['Nov. 2024',num(c.registered_2024)],['March 2026',num(c.registered_march_2026),1],['Change since Nov. 2024',SPCT(c.registration_growth_2024_2026),1],['Texas',SPCT(S.registration_growth_2024_2026)],['On the suspense list',num(c.suspense_march_2026)+' ('+PCT(c.suspense_march_2026/c.registered_march_2026)+')']]);
  else if(v.regSince22!=null)st(`Voter registration ${v.regSince22>=0?'increased':'decreased'} since the 2022 midterm`,[['Nov. 2022',num(c.registered_2022)],['Nov. 2024',num(c.registered_2024)],['Change',SPCT(v.regSince22),1],['Texas',SPCT(TEXAS.reg_since_2022)]]);
  if(c.turnout_change_2018_2022!=null)st(`Midterm turnout ${c.turnout_change_2018_2022<0?'fell':'rose'}`,[['2018',PCT(c.turnout_2018)],['2022',PCT(c.turnout_2022)],['Change',PTS(c.turnout_change_2018_2022),1],['Texas',PTS(S.turnout_change_2018_2022)]]);
  if(c.turnout_change_2020_2024!=null)st(`Presidential turnout ${c.turnout_change_2020_2024<0?'fell':'rose'} from 2020 to 2024`,[['2020',PCT(c.turnout_2020)],['2024',PCT(c.turnout_2024)],['Change',PTS(c.turnout_change_2020_2024),1],['Texas',PTS(S.turnout_change_2020_2024)]]);
  if(c.pres_R_change_2020_2024!=null)st(`Republican presidential vote share ${c.pres_R_change_2020_2024>=0?'increased':'decreased'} from 2020 to 2024`,[['2020',PCT(c.pres_R_2020)],['2024',PCT(c.pres_R_2024)],['Change',PTS(c.pres_R_change_2020_2024),1],['Texas',PTS(S.pres_R_change_2020_2024)]]);
  if(c.pres_margin_2024!=null)st(`${c.pres_margin_2024>0?'Republicans':'Democrats'} won the 2024 presidential vote here`,[['Republican',PCT(c.pres_R_2024)+' ('+num(c.pres_R_votes_2024)+')'],['Democratic',PCT(c.pres_D_2024)+' ('+num(c.pres_D_votes_2024)+')'],['Margin',RMN(c.pres_margin_2024,2024,'pres'),1],['Texas',RMN(S.pres_margin_2024,2024,'pres')]]);
  if(c.gov_margin_2022!=null)st(`${c.gov_margin_2022>0?'Abbott':"O'Rourke"} won the 2022 governor's race here`,[['Abbott',PCT(c.gov_R_2022)+(c.gov_R_votes_2022!=null?' ('+num(c.gov_R_votes_2022)+')':'')],["O'Rourke",PCT(c.gov_D_2022)+(c.gov_D_votes_2022!=null?' ('+num(c.gov_D_votes_2022)+')':'')],['Margin',RMN(c.gov_margin_2022,2022,'gov'),1],['Texas',RMN(S.gov_margin_2022,2022,'gov')]]);
  const nw=((X.counties[f]||{})[NEW]||[]).map(([n])=>'CD '+n).join(' + '),od=((X.counties[f]||{})[OLD]||[]).map(([n])=>'CD '+n).join(' + ');
  st(v.cdChg>=0.999?"The county's congressional district changes in 2026":v.cdChg>0?"The county's congressional geography changes in 2026":"The county's congressional district number does not change in 2026",[['2024 map',od||'—'],['2026 map',nw||'—'],['Residents with a new district number',PCT0(v.cdChg),1]].concat(v.leanChg!=null?[['District lean, 2024 presidential vote',RM(v.leanOld)+' → '+RM(v.leanNew)]]:[]));
  if(v.moneyN)st(`${v.moneyN===1?'One down-ballot candidate has':'Several down-ballot races have'} active fundraising`,[['Candidates reporting',num(v.moneyN)],['Raised in 2026',USDK(v.money),1],['Best-funded race',topRace(f)]]);else st('No state-district race here has reported money yet',[['Note','TEC reports cover state offices; federal and county offices file elsewhere']]);
  const cats=CATS.filter(ct=>(ORG[f]||[]).some(o=>o.cat===ct));if(cats.length)st(`${cats.length>2?cats.slice(0,2).join(', ')+' and other sectors':cats.join(' and ')} ${cats.length===1?'has':'have'} established local organizations`,[['Organizations listed',num(v.orgs),1],['Sectors',cats.map(ct=>ct+' ('+(ORG[f]||[]).filter(o=>o.cat===ct).length+')').join(', ')]]);else st('No community organizations collected here yet',[['Note','statewide directories had no entry; add local groups where a roundtable is planned']]);
  const infra=[];if(v.rainPct!=null&&(v.rainPct<80||v.rainPct>120))infra.push(v.rainPct<80?'a dry year':'a wet year');if(v.dcN)infra.push('data-center development');
  st(infra.length?`The county has ${infra.join(' and ')} to watch`:'No major water or data-center pressure flagged',[['Rain, last 12 months',v.rainPct!=null?v.rainPct+'% of usual':'—',v.rainPct!=null&&(v.rainPct<80||v.rainPct>120)?1:0],['Wells drilled since 2020',v.wellsNew!=null?num(v.wellsNew):'—'],['Data center projects',num(v.dcN)+(v.dcMW?' ('+num(v.dcMW)+' MW announced)':''),v.dcN?1:0],['Aquifers',aqList(f)]]);
  return out;}
function topRace(f){const bc=B.counties[f];if(!bc)return '—';const t={};bc.cands.forEach(i=>{const cd=B.cands[i],o=B.offices[cd[1]];if(DOWN.has(o[1])&&raceTot[o[0]]!=null)t[o[0]]=raceTot[o[0]];});const top=Object.entries(t).sort((a,b)=>b[1]-a[1])[0];return top?title(top[0])+' ('+USDK(top[1])+')':'—';}
const title=s=>String(s).toLowerCase().replace(/\b\w/g,ch=>ch.toUpperCase()).replace(/\bOf\b/g,'of').replace(/\bThe\b/g,'the');
const aqList=f=>((AQ[f]||{}).aq||[]).map(a=>a[0]+' ('+PCT0(a[2])+(a[1]==='minor'?', minor':'')+')').join('; ')||'none mapped';
const knowHTML=f=>knowBlock(know(f));
function knowBlock(list){return `<div class="know"><div class="kt">What to know</div>${list.map(s=>`<div class="st"><b>${esc(s.t)}</b><div class="ev">${s.ev.map(([k,v,hi])=>`<span${hi?' class="chg"':''}>${esc(k)}: ${esc(String(v))}</span>`).join('')}</div></div>`).join('')}</div>`;}
// ---- tables with county, compare counties and Texas ----
function cmpTable(f,rows){const cols=[f].concat(ST.cmp.filter(x=>x!==f)).concat(['48']);
  return `<table class="cmp"><tr><th>Measure</th>${cols.map(x=>`<th>${x==='48'?'Texas':esc(cname[x])}</th>`).join('')}</tr>${rows.map(([lab,fn,fmt])=>`<tr><td>${lab}</td>${cols.map((x,i)=>{const v=fn(x);return `<td${i===0?' class="me"':''}>${v==null||v===''||(typeof v==='number'&&isNaN(v))?'—':fmt(v)}</td>`;}).join('')}</tr>`).join('')}</table>`;}
const H=t=>`<div class="h3">${t}</div>`;
// ---- tabs ----
const TOPIND=['Agriculture, forestry, fishing, hunting & mining (%)','Construction (%)','Manufacturing (%)','Wholesale trade (%)','Retail trade (%)','Transportation, warehousing & utilities (%)','Information (%)','Finance, insurance & real estate (%)','Professional, scientific, management & administrative services (%)','Educational services & health care (%)','Arts, entertainment, recreation, accommodation & food services (%)','Other services (%)','Public administration (%)'];
const topInd=(f,n)=>TOPIND.map(k=>[k.replace(' (%)',''),d(f,k)]).filter(x=>x[1]!=null).sort((a,b)=>b[1]-a[1]).slice(0,n);
function tabOverview(f){return H('Who lives here?')+cmpTable(f,[['Population, July 2025',x=>d(x,'Population, July 1 2025 (TDC prelim.)'),num],['Population change since 2020',x=>d(x,'Pop. change 2020-2025 (%)'),SPCT],['Adults 18 and over',x=>d(x,'Adults 18+ (ACS 2020-24)'),num],['Registered voters, March 2026',x=>e(x,'registered_march_2026'),num],['Change in registration, Nov. 2024 to March 2026',x=>e(x,'registration_growth_2024_2026'),SPCT],['On the suspense list, March 2026',x=>e(x,'suspense_march_2026'),num],['Registered voters, Nov. 2024',x=>e(x,'registered_2024'),num],['Registered as a share of adults (March 2026)',x=>x==='48'?S.registered_march_2026/TXD['Adults 18+ (ACS 2020-24)']:V[x].regOfAdults,PCT0],['Turnout 2024',x=>e(x,'turnout_2024'),PCT],['Turnout 2022 (midterm)',x=>e(x,'turnout_2022'),PCT],['Median age',x=>d(x,'Median age'),v=>v.toFixed(1)],['Hispanic',x=>d(x,'Hispanic (%)'),PCT],['White, non-Hispanic',x=>d(x,'Non-Hispanic White (%)'),PCT],['Black, non-Hispanic',x=>d(x,'Non-Hispanic Black (%)'),PCT],['Asian, non-Hispanic',x=>d(x,'Non-Hispanic Asian (%)'),PCT],['Median household income',x=>d(x,'Median household income ($)'),USD],['Poverty rate',x=>d(x,'Poverty rate (%)'),PCT],["Bachelor's degree or higher",x=>d(x,"Bachelor's degree or higher, 25+ (%)"),PCT],['Unemployment',x=>d(x,'Unemployment rate (%)'),PCT],['Homeownership',x=>d(x,'Homeownership rate (%)'),PCT]])
  +`<div class="ccnote">Largest industries (share of employed residents): ${topInd(f,4).map(x=>esc(x[0])+' '+PCT0(x[1])).join(' · ')}.</div>`
  +(()=>{const ps=PL.filter(p=>p[1]===f).sort((a,b)=>(b[5]||0)-(a[5]||0));if(!ps.length)return '';const show=ps.slice(0,12);return `<div class="ccnote"><b>Cities and places</b> (${num(ps.length)}): ${show.map(p=>esc(p[0])+(p[4]==='CDP'?' (community'+(p[5]?', '+p[5]+' sq mi)':')'):(p[4]==='city'?(p[5]?' ('+p[5]+' sq mi)':''):' ('+esc(p[4])+(p[5]?', '+p[5]+' sq mi':'')+')'))).join(', ')}${ps.length>12?' and '+num(ps.length-12)+' more':''}. Census 2024 Gazetteer; a place that straddles counties is listed under the county of its center point.</div>`;})()
  +`<details><summary>More about who lives here</summary>`+cmpTable(f,[['Population estimate, Jan. 2026 (TDC prelim.)',x=>d(x,'Population, Jan 1 2026 (TDC prelim.)'),num],['Population change 2020 to Jan. 2026',x=>d(x,'Pop. change 2020-2026 (%)'),SPCT],['Census 2020 count',x=>d(x,'Census 2020 count'),num],['Population, ACS 2020-24',x=>d(x,'Population, ACS 2020-24'),num],['Male',x=>d(x,'Male (%)'),PCT],['Female',x=>d(x,'Female (%)'),PCT],['Other or multiracial, non-Hispanic',x=>d(x,'Other / multiracial, non-Hispanic (%)'),PCT],['Per-capita income',x=>d(x,'Per-capita income ($)'),USD],['Labor-force participation, 16+',x=>d(x,'Labor-force participation, 16+ (%)'),PCT],['Employed civilians 16+',x=>d(x,'Employed civilians 16+ (count)'),num],['Median home value',x=>d(x,'Median home value ($)'),USD],['Median gross rent',x=>d(x,'Median gross rent ($)'),USD]])+`</details>`
  +H('Property taxes')+cmpTable(f,[[`County government tax rate ${PTY} (per $100)`,x=>ptc(x,PTY),RATE],[`County government tax rate ${PTY-1}`,x=>ptc(x,PTY-1),RATE],[`County government tax rate ${PT0}`,x=>ptc(x,PT0),RATE],[`Change ${PT0} to ${PTY} (per $100)`,x=>{const a=ptc(x,PT0),b=ptc(x,PTY);return a!=null&&b!=null?b-a:null;},v=>(v>0?'+':'')+v.toFixed(4)],[`Average school district rate ${PTY}`,x=>pti(x,PTY),RATE],[`Taxing units in the county, ${PTY}`,x=>x==='48'?null:((PT.counties[x]||{n:{}}).n||{})[PTY],num]])
  +(()=>{const u=(PT.counties[f]||{}).units||[];return u.length?`<details><summary>Every taxing unit in ${esc(cname[f])} County, ${PTY} (${u.length})</summary><table class="cmp"><tr><th style="text-align:left">Taxing unit</th><th style="text-align:left">Type</th><th>Rate</th></tr>${u.map(x=>`<tr><td>${esc(x[0])}${x[3]?' <small>(also in other counties)</small>':''}</td><td style="text-align:left">${esc(x[1])}</td><td class="me">${RATE(x[2])}</td></tr>`).join('')}</table></details>`:'';})()+`<div class="ccnote">${(()=>{const fl=((PT.counties[f]||{}).flagged||{})[PTY];return fl!=null?`<b>${PTY} county rate left blank:</b> the Comptroller's ${PTY} file lists ${RATE(fl)} for this county, which is not consistent with ${PTY-1} (its file misfiles some county rows); confirm the adopted rate with the county before using it. `:'';})()}Texas Comptroller, total tax rates by taxing unit (per $100 of taxable value); the Texas figure is the unweighted average of the county rates. The ${PTY} file was checked against adopted rates (Lubbock ${RATE(0.327425)}, Harris ${RATE(0.38096)} match); ${PTY} county rates that moved more than half from ${PTY-1} are left blank as unverified.</div>`
  +H('Key changes over time')+cmpTable(f,[['Population growth 2020 to 2025',x=>d(x,'Pop. change 2020-2025 (%)'),SPCT],['Registration growth 2020 to 2024',x=>e(x,'registration_growth_2020_2024'),SPCT],['Registration growth minus population growth',x=>x==='48'?TEXAS.reg_vs_pop:V[x].regVsPop,PTS],['Republican presidential change 2020 to 2024',x=>e(x,'pres_R_change_2020_2024'),PTS],['Presidential margin change 2016 to 2024',x=>e(x,'pres_margin_change_2016_2024'),PTS],['Midterm turnout change 2018 to 2022',x=>e(x,'turnout_change_2018_2022'),PTS]])
  +`<div class="ccnote">Sources: Texas Demographic Center preliminary 2025 estimates; ACS 2020-24 five-year; Texas Secretary of State registration and canvass; Texas Legislative Council county subtotals 2020-24.</div>`;}
const PAIRS=[['2020-2024','2020 vs 2024','pres'],['2016-2020','2016 vs 2020','pres'],['2018-2022','2018 vs 2022','gov'],['2014-2018','2014 vs 2018','gov']];
function tabElections(f){const c=E.counties[f]||{};const [a,b]=ST.pair.split('-').map(Number);const kind=PAIRS.find(p=>p[0]===ST.pair)[2];const RN={2016:'Trump',2020:'Trump',2024:'Trump',2014:'Abbott',2018:'Abbott',2022:'Abbott'},DN={2016:'Clinton',2020:'Biden',2024:'Harris',2014:'Davis',2018:'Valdez',2022:"O'Rourke"};
  const rows=kind==='pres'?[[`Republican share (${RN[a]} / ${RN[b]})`,x=>e(x,'pres_R_'+a),x=>e(x,'pres_R_'+b),PCT],[`Democratic share (${DN[a]} / ${DN[b]})`,x=>e(x,'pres_D_'+a),x=>e(x,'pres_D_'+b),PCT],['Republican votes',x=>e(x,'pres_R_votes_'+a),x=>e(x,'pres_R_votes_'+b),num],['Democratic votes',x=>e(x,'pres_D_votes_'+a),x=>e(x,'pres_D_votes_'+b),num],['Margin',x=>e(x,'pres_margin_'+a),x=>e(x,'pres_margin_'+b),RM],['Turnout',x=>e(x,'turnout_'+a),x=>e(x,'turnout_'+b),PCT],['Registered voters',x=>e(x,'registered_'+a),x=>e(x,'registered_'+b),num]]
    :[[`Republican share (${RN[a]} / ${RN[b]})`,x=>e(x,'gov_R_'+a),x=>e(x,'gov_R_'+b),PCT],[`Democratic share (${DN[a]} / ${DN[b]})`,x=>e(x,'gov_D_'+a),x=>e(x,'gov_D_'+b),PCT],['Republican votes',x=>e(x,'gov_R_votes_'+a),x=>e(x,'gov_R_votes_'+b),num],['Democratic votes',x=>e(x,'gov_D_votes_'+a),x=>e(x,'gov_D_votes_'+b),num],['Governor margin (R minus D)',x=>e(x,'gov_margin_'+a),x=>e(x,'gov_margin_'+b),RM],['Turnout',x=>e(x,'turnout_'+a),x=>e(x,'turnout_'+b),PCT],['Registered voters',x=>e(x,'registered_'+a),x=>e(x,'registered_'+b),num]];
  const cols=[f].concat(ST.cmp.filter(x=>x!==f)).concat(['48']);const chg=(fa,fb,x,fmt)=>{const va=fa(x),vb=fb(x);if(va==null||vb==null)return '—';return fmt===num?SPCT(vb/va-1):fmt===PCT||fmt===RM?PTS(vb-va):fmt(vb-va);};
  const pairTable=`<table class="cmp"><tr><th>Measure</th>${cols.map(x=>`<th>${x==='48'?'Texas':esc(cname[x])}<br><small>${a} → ${b}</small></th>`).join('')}</tr>${rows.map(([lab,fa,fb,fmt])=>`<tr><td>${lab}</td>${cols.map((x,i)=>{const va=fa(x),vb=fb(x);return `<td${i===0?' class="me"':''}>${va==null?'—':fmt(va)} → ${vb==null?'—':fmt(vb)}<br><small>${chg(fa,fb,x,fmt)}</small></td>`;}).join('')}</tr>`).join('')}</table>`;
  const votes=(r,d,t)=>x=>[e(x,r),e(x,d),t?e(x,t):null],vfmt=v=>v[0]==null?'—':num(v[0])+' / '+num(v[1])+(v[2]?' of '+num(v[2]):'');
  return H('How politically active is the county, and how has it voted?')+H('How did the county vote most recently?')+cmpTable(f,[['2024 President: Trump',x=>e(x,'pres_R_2024'),PCT],['2024 President: Harris',x=>e(x,'pres_D_2024'),PCT],['2024 President: margin',x=>e(x,'pres_margin_2024'),v=>RMN(v,2024,'pres')],['2024 votes (Trump / Harris)',votes('pres_R_votes_2024','pres_D_votes_2024','pres_total_votes_2024'),vfmt],['2024 U.S. Senate: Cruz',x=>e(x,'sen_R_2024'),PCT],['2024 U.S. Senate: Allred',x=>e(x,'sen_D_2024'),PCT],['2024 U.S. Senate: margin',x=>e(x,'sen_margin_2024'),v=>RMN(v,2024,'sen')],['2024 votes (Cruz / Allred)',votes('sen_R_votes_2024','sen_D_votes_2024','sen_total_votes_2024'),vfmt],['2022 Governor: Abbott',x=>e(x,'gov_R_2022'),PCT],["2022 Governor: O'Rourke",x=>e(x,'gov_D_2022'),PCT],['2022 Governor: margin',x=>e(x,'gov_margin_2022'),v=>RMN(v,2022,'gov')],["2022 votes (Abbott / O'Rourke)",votes('gov_R_votes_2022','gov_D_votes_2022','gov_total_votes_2022'),vfmt]])
    +H('Other statewide races, most recent')+cmpTable(f,DBORDER.filter(k=>dbLatest(k)).map(k=>{const y=dbLatest(k),n=dbName(k,y);return [`${y} ${DB.races[k].label}: ${n[0]} vs ${n[1]}`,x=>dbMargin(x,k,y),v=>RMD(v,k,y)];}))
    +`<details><summary>Every down-ballot statewide race since 2006, ${esc(cname[f])} vs Texas</summary><table class="cmp"><tr><th style="text-align:left">Race</th><th>${esc(cname[f])}</th><th>Texas</th></tr>${DBORDER.flatMap(k=>Object.keys((DB.races[k]||{}).years||{}).map(Number).sort((a,b)=>b-a).map(y=>{const n=dbName(k,y),m=dbMargin(f,k,y),st=dbMargin('48',k,y),rs=dbShare(f,k,y,0),ds=dbShare(f,k,y,1);return `<tr><td>${y} ${esc(DB.races[k].label)}<br><small>${esc(n[0])} ${rs!=null?PCT(rs):'—'} · ${esc(n[1])} ${ds!=null?PCT(ds):'—'}</small></td><td class="me">${RMD(m,k,y)}</td><td>${RMD(st,k,y)}</td></tr>`;})).join('')}</table><div class="ccnote">Lieutenant Governor, Attorney General, Comptroller, Land and Agriculture Commissioner, Railroad Commissioner, Chief Justice and Presiding Judge races; each party's top vote-getter statewide. SOS canvass 2006-2018, TLC county subtotals 2020-2024.</div></details>`
    +H('Change between two elections')+pairTable
    +H('Presidential trend')+cmpTable(f,[['Trump 2016',x=>e(x,'pres_R_2016'),PCT],['Trump 2020',x=>e(x,'pres_R_2020'),PCT],['Trump 2024',x=>e(x,'pres_R_2024'),PCT],['Democratic 2016',x=>e(x,'pres_D_2016'),PCT],['Democratic 2020',x=>e(x,'pres_D_2020'),PCT],['Democratic 2024',x=>e(x,'pres_D_2024'),PCT],['Margin 2016',x=>e(x,'pres_margin_2016'),v=>RMN(v,2016,'pres')],['Margin 2020',x=>e(x,'pres_margin_2020'),v=>RMN(v,2020,'pres')],['Margin 2024',x=>e(x,'pres_margin_2024'),v=>RMN(v,2024,'pres')],['Shift 2016 to 2024 (Trump share)',x=>e(x,'pres_R_change_2016_2024'),PTS]])
    +H('Midterms and other statewide races')+cmpTable(f,[['Governor 2018 margin',x=>e(x,'gov_margin_2018'),v=>RMN(v,2018,'gov')],['Governor 2022 margin',x=>e(x,'gov_margin_2022'),v=>RMN(v,2022,'gov')],['Governor swing 2018 to 2022',x=>e(x,'gov_margin_change_2018_2022'),PTS],['U.S. Senate 2018 margin',x=>e(x,'sen_margin_2018'),v=>RMN(v,2018,'sen')],['U.S. Senate 2020 margin',x=>e(x,'sen_margin_2020'),v=>RMN(v,2020,'sen')],['U.S. Senate 2024 margin',x=>e(x,'sen_margin_2024'),v=>RMN(v,2024,'sen')],['Turnout 2018',x=>e(x,'turnout_2018'),PCT],['Turnout 2022',x=>e(x,'turnout_2022'),PCT],['Primary turnout 2018 (D + R)',x=>e(x,'primary_turnout_2018'),PCT],['Primary votes 2018 (Democratic / Republican)',votes('primary_D_votes_2018','primary_R_votes_2018'),vfmt],['Democratic share of 2018 primary votes',x=>e(x,'primary_D_share_2018'),PCT]])
    +H('Turnout and ballots by election')+`<table class="cmp"><tr><th style="text-align:left">Year</th><th>Registered</th><th>Ballots cast</th><th>Top-race votes</th><th>Turnout</th><th>Texas</th></tr>${[2024,2022,2020,2018,2016,2014,2012,2010,2008,2006].map(y=>{const r=e(f,'registered_'+y),b=e(f,'ballots_'+y),tv=e(f,(y%4===0?'pres':'gov')+'_total_votes_'+y),t=e(f,'turnout_'+y),st=S['turnout_'+y];if(r==null)return '';return `<tr><td>${y}</td><td>${num(r)}</td><td>${b!=null?num(b):'—'}</td><td>${tv!=null?num(tv):'—'}</td><td class="me">${t!=null?PCT(t):'—'}</td><td>${st!=null?PCT(st):'—'}</td></tr>`;}).join('')}</table><div class="ccnote">Ballots cast = every ballot counted (TLC, 2012-2024; top-race votes before 2012). Turnout = top-race votes / registered voters.</div>`
    +H('Registration and the suspense list over time')+(()=>{const idx=REG.pages.map((p,i)=>i).filter(i=>REG.pages[i][3]===11||i>=REG.pages.length-4);const rows=idx.slice().reverse().map(i=>{const [r,su]=regAt(f,i),[R,SU]=regAt('48',i);return `<tr><td>${esc(REG.pages[i][0])}</td><td class="me">${r!=null?num(r):'—'}</td><td>${su!=null?num(su):'—'}</td><td class="me">${r&&su!=null?PCT(su/r):'—'}</td><td>${R&&SU!=null?PCT(SU/R):'—'}</td></tr>`;}).join('');return `<table class="cmp"><tr><th style="text-align:left">As of</th><th>Registered</th><th>Suspense list</th><th>Share</th><th>Texas share</th></tr>${rows}</table><details><summary>Every SOS registration page since 2008 (${REG.pages.length})</summary><table class="cmp"><tr><th style="text-align:left">As of</th><th>Registered</th><th>Suspense</th><th>Share</th></tr>${REG.pages.map((p,i)=>{const [r,su]=regAt(f,i);return `<tr><td>${esc(p[0])}</td><td>${r!=null?num(r):'—'}</td><td>${su!=null?num(su):'—'}</td><td>${r&&su!=null?PCT(su/r):'—'}</td></tr>`;}).reverse().join('')}</table></details><div class="ccnote">Suspense list = registered voters whose address the county could not confirm; they stay registered and can vote after confirming an address, and are removed after two federal general elections without contact. SOS registration figures, every January, March and November since 2008.</div>`;})()
    +`<div class="ccnote">Margins are Republican minus Democratic share of all votes; changes in points; turnout = top-race votes / registered voters. SOS canvass 2006-2018, TLC county subtotals 2020-2024, SOS county pages for the 2014-2018 primaries.</div>`;}
// one candidate: name, party, and the totals from the TEC or FEC when there are any
const candRow=(cd,i,n,f)=>`<div class="org">${cd[3]!=null?`<small>#${i+1} of ${n}</small> `:''}<b>${esc(cd[0])}</b> <span style="color:${cd[2]==='REP'?'#a91b1b':cd[2]==='DEM'?'#1b4fa6':'var(--ink3)'};font-weight:600">${esc(cd[2])}</span>${cd[3]!=null?`<br>Raised ${USD(cd[3])} · Cash on hand ${cd[4]!=null?USD(cd[4]):'—'} · Spent ${cd[10]!=null?USD(cd[10]):'—'}${cd[12]?' · Loans '+USD(cd[12]):''}${cd[6]!=null&&cd[6]!==cd[3]?' · Since 2025 '+USD(cd[6]):''}<br><small>${(cd[7]||'').includes('FEC')?'FEC 2025-26 cycle totals':'Candidate account (TEC)'}, filed through ${esc(cd[5]||'—')}${cd[8]?'; associated committees: '+esc(cd[8])+' (raised '+(cd[9]!=null?USD(cd[9]):'—')+' since 2025'+(cd[11]!=null?', cash '+USD(cd[11]):'')+')':''}</small>`:`<br><small>${(cd[7]||'').includes('FEC')?'no FEC summary':'files with a county or local authority; not in the TEC export'}</small>`}${(()=>{const x=f?fromCounty(cd,f):null;return x?`<br><small class="fromc">From ${esc(cname[f])} County donors: <b>${USD(x[0])}</b> in 2026 (${num(x[1])} gifts)${shareOf(x[0],cd)?', '+shareOf(x[0],cd)+' of the total':''}; ${USD(x[2])} since 2025</small>`:f&&cd[3]!=null&&!(cd[7]||'').includes('FEC')?`<br><small class="fromc">No itemized gifts from ${esc(cname[f])} County donors</small>`:'';})()}</div>`;
function tabMoney(f){const bc=B.counties[f]||{cands:[]};const byOff={};bc.cands.forEach(i=>{const cd=B.cands[i];const o=B.offices[cd[1]];(byOff[o[0]+'|'+o[1]]=byOff[o[0]+'|'+o[1]]||[]).push(cd);});
  const races=Object.keys(byOff).filter(k=>DOWN.has(k.split('|')[1])).map(k=>{const cs=byOff[k].slice().sort((a,b)=>(b[3]||0)-(a[3]||0));return {name:k.split('|')[0],level:k.split('|')[1],cs,tot:cs.reduce((a,x)=>a+(x[3]||0),0),any:cs.some(x=>x[3]!=null)};}).sort((a,b)=>b.tot-a.tot||a.name.localeCompare(b.name));
  const row=candRow;
  const fed=Object.keys(byOff).filter(k=>k.endsWith('|Federal')),stw=Object.keys(byOff).filter(k=>k.endsWith('|Statewide'));
  const givers=[];Object.keys(CT.cands).forEach(i=>{const x=CT.cands[i][f];if(x&&x[0]>0)givers.push([+i,x]);});Object.keys(CT.spacs).forEach(i=>{const x=CT.spacs[i][f];if(!x||!x[0])return;const g=givers.find(y=>y[0]===+i);if(g)g[1]=g[1].map((v,k)=>v+x[k]);else givers.push([+i,x.slice()]);});givers.sort((a,b)=>b[1][0]-a[1][0]);
  return H('Where is campaign money flowing?')+`<div class="box"><b>${num(V[f].moneyN)}</b> candidates in state-district races on this ballot report <b>${USDK(V[f].money)}</b> raised in 2026 (TEC). Best-funded race: ${esc(topRace(f))}.</div>`
    +H('Who gives here?')+`<div class="box">Donors in ${esc(cname[f])} County gave <b>${USDK(V[f].contrib)}</b> in itemized contributions to 2026 state candidates in 2026 (${num(V[f].contribN)} gifts to ${num(givers.length)} candidates or their committees): <b>${USDK(V[f].contribR)}</b> to Republican candidates and <b>${USDK(V[f].contribD)}</b> to Democratic candidates${V[f].govDshare!=null?`; in the governor's race ${PCT0(V[f].govDshare)} of the county's dollars went to the Democratic candidate`:''}.</div>`
    +(givers.length?`<div class="cat">Candidates receiving the most from ${esc(cname[f])} County donors</div>`+givers.slice(0,10).map(([i,x],k)=>{const cd=B.cands[i];return `<div class="org"><small>#${k+1}</small> <b>${esc(cd[0])}</b> <span style="color:${cd[2]==='REP'?'#a91b1b':cd[2]==='DEM'?'#1b4fa6':'var(--ink3)'};font-weight:600">${esc(cd[2])}</span> <small>· ${esc(title(B.offices[cd[1]][0]))}</small><br><small>${USD(x[0])} in 2026 (${num(x[1])} gifts)${shareOf(x[0],cd)?' · '+shareOf(x[0],cd)+' of what the candidate raised':''}${cd[8]?' · includes '+esc(cd[8].replace(/\s*\(\d{8}\)/g,''))+'':''} · ${USD(x[2])} since 2025</small></div>`;}).join(''):'<div class="ccnote">No itemized contributions from this county\'s donors in 2026.</div>')
    +(races.length?races.map(r=>`<div class="cat">${esc(title(r.name))} <small>· ${r.any?USDK(r.tot)+' raised in 2026':'no TEC data'}</small></div>${r.any&&r.level==='State district'&&r.tot>=HIGH?`<div class="ccnote"><b>One of the higher-funded down-ballot races affecting the county</b> (top quarter of State House, Senate and SBOE race totals statewide, ${USDK(HIGH)} and up).</div>`:''}${r.cs.map((cd,i)=>row(cd,i,r.cs.length,f)).join('')}`).join(''):'<div class="ccnote">No district-level races on this ballot.</div>')
    +`<details><summary>U.S. House and Senate on this ballot (FEC, 2025-26 cycle)</summary>${fed.map(k=>`<div class="cat">${esc(title(k.split('|')[0]))}</div>${byOff[k].slice().sort((a,b)=>(b[3]||0)-(a[3]||0)).map((cd,i)=>row(cd,i,byOff[k].length,f)).join('')}`).join('')}</details>`
    +`<details><summary>Statewide races (same on every ballot)</summary>${stw.map(k=>`<div class="cat">${esc(title(k.split('|')[0]))}</div>${byOff[k].slice().sort((a,b)=>(b[3]||0)-(a[3]||0)).map((cd,i)=>row(cd,i,byOff[k].length,f)).join('')}`).join('')}</details>`
    +`<div class="ccnote">Texas Ethics Commission bulk export as of 2026-09-26 (2026 year to date through each candidate's latest report); FEC bulk candidate summary as of 2026-09-28 (cycle totals). County offices file locally and are blank. "From county donors" = itemized contributions (TEC Schedule A) placed by the donor\'s ZIP or city; unitemized gifts and federal candidates\' donors are not placed.</div>`;}
const LEVELS=['Federal','Statewide','State district','Judicial district','District attorney','County / precinct'];
function chairHTML(f){const ch=(B.counties[f]||{}).chair||{};return ch.name?`<div class="box"><b>Democratic county chair</b><br>${esc(ch.name)}${ch.email?'<br><small>'+ch.email.split(' / ').map(m=>'<a href="mailto:'+esc(m.trim())+'">'+esc(m.trim())+'</a>').join(' / ')+'</small>':''}${ch.phone?'<br><small>'+esc(ch.phone)+'</small>':''}<br><small>Texas Democratic Party county chair directory</small></div>`:`<div class="box"><b>Democratic county chair</b><br><small>${esc(ch.status||'No chair listed')}</small></div>`;}
function tabBallot(f){const bc=B.counties[f]||{cands:[]};const byOff={};const order=[];bc.cands.forEach(i=>{const cd=B.cands[i],o=B.offices[cd[1]];const k=o[0]+'|'+o[1];if(!byOff[k]){byOff[k]=[];order.push(k);}byOff[k].push(cd);});
  const counts=LEVELS.map(l=>[l,order.filter(k=>k.endsWith('|'+l)).reduce((a,k)=>a+byOff[k].length,0)]).filter(x=>x[1]);
  return H('What is on the 2026 ballot, and who are the party contacts?')+chairHTML(f)+`<div class="box"><b>${num(bc.cands.length)}</b> candidates for <b>${num(order.length)}</b> offices on the certified 2026 general-election ballot: ${counts.map(([l,n])=>n+' '+l.toLowerCase()).join(', ')}.</div>`
    +LEVELS.map(l=>{const ks=order.filter(k=>k.endsWith('|'+l));if(!ks.length)return '';return `<div class="cat">${esc(l)}</div>`+ks.map(k=>{const cs=byOff[k];const money=cs.some(c=>c[3]!=null);const sorted=money?cs.slice().sort((a,b)=>(b[3]||0)-(a[3]||0)):cs;
      return `<div class="race"><b>${esc(title(k.split('|')[0]))}</b>${cs.length===1?' <small>· unopposed</small>':''}${money?' <small>· '+USDK(cs.reduce((a,x)=>a+(x[3]||0),0))+' raised</small>':''}</div>`+sorted.map((cd,i)=>candRow(cd,i,cs.length,f)).join('');}).join('');}).join('')
    +`<div class="ccnote">Ballot: Texas Secretary of State certification of ${esc(B.ballot_cert)}. Totals: ${esc(B.fund_asof)}; FEC 2025-26 cycle totals for federal candidates. County and precinct candidates file with the county clerk, so their totals are not online.</div>`;}
function orgRow(o){return `<div class="org"><b>${esc(o.org)}</b>${o.chapter?' <small>· '+esc(o.chapter)+'</small>':''}${o.leader?'<br>'+esc(o.leader)+(o.title?', '+esc(o.title):''):''}${o.phone||o.email||o.web?'<br><small>'+[o.phone?esc(o.phone):'',o.email?'<a href="mailto:'+esc(o.email)+'">'+esc(o.email)+'</a>':'',o.web?'<a href="'+esc(o.web)+'" target="_blank" rel="noopener">website ↗</a>':''].filter(Boolean).join(' · ')+'</small>':''}${o.addr?'<br><small>'+esc(o.addr)+'</small>':''}<br><small>${esc(o.constituency||'')} · reach: ${esc(o.cover||'unknown')}${o.scope?' · area: '+esc(o.scope):''}${o.reach?' · membership/reach: '+esc(o.reach):''} · evidence: ${esc(o.evidence||'unknown')}</small>${o.notes?'<br><small>'+esc(o.notes)+'</small>':''}<br><small>Source: ${o.src?'<a href="'+esc(o.src.split(' ')[0])+'" target="_blank" rel="noopener">'+esc(o.src.replace(/^https?:\/\/(www\.)?/,'').split('/')[0])+' ↗</a>':'—'}${o.verified?' · '+esc(o.verified):''}</small></div>`;}
function contactsHTML(f){const ch=(B.counties[f]||{}).chair||{};const orgs=(ORG[f]||[]).filter(o=>o.leader||o.phone||o.email).sort((a,b)=>(b.leader?1:0)-(a.leader?1:0)||CATS.indexOf(a.cat)-CATS.indexOf(b.cat));const rows=[];
  if(ch.name)rows.push(`<div class="org"><b>${esc(ch.name)}</b> <small>· Democratic county chair</small><br><small>${[ch.phone?esc(ch.phone):'',ch.email?ch.email.split(' / ').map(m=>'<a href="mailto:'+esc(m.trim())+'">'+esc(m.trim())+'</a>').join(' / '):''].filter(Boolean).join(' · ')}</small></div>`);
  orgs.slice(0,12).forEach(o=>rows.push(`<div class="org"><b>${o.leader?esc(o.leader):esc(o.org)}</b> <small>· ${o.leader?esc(o.title||'')+(o.title?', ':'')+esc(o.org):esc(o.cat)}</small><br><small>${[o.phone?esc(o.phone):'',o.email?'<a href="mailto:'+esc(o.email)+'">'+esc(o.email)+'</a>':'',o.web?'<a href="'+esc(o.web)+'" target="_blank" rel="noopener">website ↗</a>':''].filter(Boolean).join(' · ')}${o.notes&&/verify/i.test(o.notes)?' · <i>verify before contacting</i>':''}</small></div>`));
  return rows.length?H('Who should I talk to?')+`<div class="ccnote">Public-facing contact points: the county chair first, then organizations with a named leader, then the rest with a phone or email. Every organization is listed by sector below with its source.</div>`+rows.join(''):'';}
function tabCommunity(f){const orgs=ORG[f]||[];const by={};orgs.forEach(o=>{(by[o.cat]=by[o.cat]||[]).push(o);});const order=c=>{const i=CATS.indexOf(c);return i<0?99:i;};
  return contactsHTML(f)+H('Which organizations are present here?')+`<div class="ccnote">${esc(O.definition||'')} <i>${esc(O.caution||'')}</i></div>`+(orgs.length?Object.keys(by).sort((a,b)=>order(a)-order(b)).map(ct=>`<div class="cat">${esc(ct)} <small>(${by[ct].length})</small></div>${by[ct].map(orgRow).join('')}`).join(''):'<div class="ccnote">No organizations collected for this county yet. The statewide directories gathered so far had no entry here; add local groups where a roundtable is planned.</div>')
    +`<div class="ccnote">Collected so far: ${esc((O.waves||[]).map(w=>w.done?w.label+' ✓':w.label+' (pending)').join(' · '))}.</div>`;}
function tabDistricts(f){const plan=ST.dmap;const parts=(X.counties[f]||{})[plan]||[];const lab=plan===NEW?'2026 map (PLANC2333)':'2024 map (PLANC2193)';
  const rows=parts.map(([n,p,sh])=>[CM.districtName(plan,n)+(sh<0.995?' ('+PCT0(sh)+' of county)':''),RM(marg(plan,2016,'pres',n)),RM(marg(plan,2020,'pres',n)),RM(marg(plan,2024,'pres',n)),RM(marg(plan,2022,'gov',n)),RM(marg(plan,2024,'sen',n))]);
  return H('What changed because of redistricting?')
    +`<div class="box"><b>2024 map (PLANC2193):</b> ${((X.counties[f]||{})[OLD]||[]).map(([n,p,sh])=>'CD '+n+(sh<0.995?' ('+PCT0(sh)+')':'')).join(' + ')||'—'}<br><b>2026 map (PLANC2333):</b> ${((X.counties[f]||{})[NEW]||[]).map(([n,p,sh])=>'CD '+n+(sh<0.995?' ('+PCT0(sh)+')':'')).join(' + ')||'—'}<br>${V[f].cdChg>=0.999?'<b>The whole county has a new district number under the 2026 map.</b>':V[f].cdChg>0?'<b>The county is split differently under the 2026 map</b> ('+PCT0(V[f].cdChg)+' of residents have a new district number).':'The district number here did not change under the 2026 map.'}${V[f].leanChg!=null?'<br>2024 presidential vote under the old district: <b>'+RM(V[f].leanOld)+'</b>; re-tabulated into the 2026 district: <b>'+RM(V[f].leanNew)+'</b>.':''}</div>`
    +H('Districts affecting the county on the '+lab)+`<table class="cmp"><tr><th>District</th><th>Pres. 2016</th><th>Pres. 2020</th><th>Pres. 2024</th><th>Gov. 2022</th><th>Sen. 2024</th></tr>${rows.map(r=>`<tr>${r.map((c,i)=>`<td${i===0?' class="me"':''}>${c}</td>`).join('')}</tr>`).join('')}</table>`
    +parts.map(([n])=>CM.districtRow(plan,n,RM(marg(plan,2024,'pres',n)),'open this district')).join('')
    +`<div class="ccnote">Legislative districts: ${['PLANH2316','PLANS2168','PLANE2106'].map(pl=>((X.counties[f]||{})[pl]||[]).map(([n,p,sh])=>CM.districtName(pl,n)+(sh<0.995?' ('+PCT0(sh)+')':'')).join(', ')).filter(Boolean).join(' · ')||'—'}. Results on the 2026 lines are Texas Legislative Council re-tabulations of actual votes (Red-206); county shares are 2020 Census residents.</div>`;}
function tabWater(f){const w=W[f]||{};const aq=(AQ[f]||{}).aq||[];const uses=o=>Object.entries(o||{}).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([k,v])=>k+' '+num(v)).join(' · ');
  return H('What water and aquifer context matters?')+`<div class="box"><b>Rain:</b> ${w.p!=null?w.p+'% of the county\'s usual year in the last twelve months':'no data'}${w.r?' (usual: '+w.r+' inches a year, 1991-2020 average)':''}.<br><b>Groundwater:</b> ${aq.length?aq.map(a=>esc(a[0])+' ('+PCT0(a[2])+' of the county'+(a[1]==='minor'?', minor aquifer':'')+')').join('; '):'no mapped aquifer'}.<br><b>Wells:</b> ${w.w!=null?num(w.w)+' on record':'—'}; ${w.nw!=null?num(w.nw)+' drilled since 2020':'—'}${w.nwu?' ('+uses(w.nwu)+')':''}.</div>`
    +cmpTable(f,[['Rain, last 12 months vs. usual',x=>x==='48'?null:V[x].rainPct,v=>v+'%'],['Usual rainfall (in/yr)',x=>x==='48'?null:V[x].rain,v=>v.toFixed(1)],['Wells on record',x=>x==='48'?WD.total:V[x].wells,num],['Wells drilled since 2020',x=>x==='48'?WD.nw_total:V[x].wellsNew,num],['Data center projects',x=>x==='48'?TEXAS.dc_n:V[x].dcN,num]])
    +`<div class="acts">${aq.map(a=>`<button type="button" data-aq="${esc(a[0])}" title="Which counties and data centers sit over this aquifer">${esc(a[0])}: what sits on top</button>`).join('')}<button type="button" data-layer="rivers">${CM.state.rivers?'Hide':'Show'} rivers &amp; lakes</button><button type="button" data-layer="basins">${CM.state.basins?'Hide':'Show'} river basins</button><button type="button" data-layer="aquifers">${CM.state.aquifers?'Hide':'Show'} aquifers on the map</button><a href="texas_aquifers_map.html" target="_blank" rel="noopener">Aquifer map ↗</a><a href="texas_rainfall_map.html" target="_blank" rel="noopener">Rainfall map ↗</a><a href="texas_wells_map.html" target="_blank" rel="noopener">Wells map ↗</a></div>`
    +`<div class="ccnote">Rain: PRISM Climate Group (county means, ${esc(WD.generated||'2026-09-25')}). Wells: TWDB groundwater database and driller reports. Aquifers: TWDB major and minor aquifer outlines, share of county area by grid sampling.</div>`;}
function tabDC(f){const inc=INC.counties[f]||{},bd=inc.burden,links=inc.links||[];const incHTML=(inc.deals_n||bd||links.length)?H('Incentives, grid demand and donor links')+`<div class="box">${inc.deals_n?`<b>${num(inc.deals_n)}</b> local incentive deals recorded here (${Object.entries(inc.by_program||{}).sort((a,b)=>b[1]-a[1]).map(([p,n])=>esc(p)+' '+num(n)).join(', ')}); reported value <b>${USDK(inc.value_total||0)}</b> where a figure is given.`:'No local incentive deal recorded for this county.'}${bd?` ERCOT queue: <b>${num(bd.queued_mw)} MW</b> across ${num(bd.gis_projects)} projects${bd.fuels?' ('+esc(bd.fuels)+')':''}; subsidized power deals: ${num(bd.power_deals)}${bd.subsidy?' ('+USDK(bd.subsidy)+')':''}.`:''}${inc.zone?` ERCOT region: ${esc(inc.zone)}.`:''}</div>`+((inc.deals||[]).length?`<div class="cat">Largest recorded deals</div>`+inc.deals.map(x=>`<div class="org"><b>${esc(x.company||'(company not named)')}</b> <small>· ${esc(x.program)}${x.level?' · '+esc(x.level):''}${x.govt?' · '+esc(x.govt):''}</small><br><small>${x.year?esc(x.year)+' · ':''}${x.value?'reported value '+USD(x.value):'value not reported'}${x.invest?' · investment '+USD(x.invest):''}${x.status?' · '+esc(x.status):''}${x.sector?' · '+esc(x.sector):''}${x.jobs?' · jobs promised '+esc(x.jobs):''}</small></div>`).join(''):'')
    +(links.length?`<div class="cat">Data-center projects linked to Abbott donors (${links.length})</div>`+links.map(l=>`<div class="org"><b>${esc(l.project)}</b>${l.campus&&l.campus!==l.project?' <small>· '+esc(l.campus)+'</small>':''}<br><small>${[l.city,l.status,l.open?'open '+l.open:'',l.announced?'announced '+l.announced:'',l.mw?l.mw+' MW':'',l.acres?l.acres+' acres':'',l.invest?'investment '+USD(+l.invest):''].filter(Boolean).map(esc).join(' · ')}</small><br><small><b>Linked giving to Abbott:</b> ${USD(l.lifetime)} lifetime (2013 to June 2026)${l.ann_year?'; '+USD(l.ann_year)+' in the announcement year':''}${l.lifetime_broader?'; broader links '+USD(l.lifetime_broader):''} · ${esc(l.tier)}</small><br><small>Donors: ${esc(l.donors||'—')}${l.owner?' · Owner: '+esc(l.owner):''}</small>${l.tax_break?`<br><small>Tax break: ${esc(l.tax_break)}${l.tax_terms?' — '+esc(l.tax_terms):''}</small>`:''}<br><small>${esc(l.confidence)}${l.src?' · <a href="'+esc(l.src)+'" target="_blank" rel="noopener">project source ↗</a>':''}${l.donation_src?' · <a href="'+esc(l.donation_src)+'" target="_blank" rel="noopener">TEC search ↗</a>':''}</small></div>`).join('')+`<div class="ccnote">Audited donor-link file: conservative relationship matches between project owners, partners and suppliers and their giving to Abbott; not proof of causation.</div>`:'')
    +`<div class="ccnote">Incentive deals and ERCOT queue figures: the incentives project on this drive (Comptroller Ch.380/381/312/313 registries, JETI agreements, ERCOT GIS reports); county as reported or derived; many deals report no dollar value.</div>`:'';
  const list=(DCC[f]||[]).slice().sort((a,b)=>(b.mw||0)-(a.mw||0));const LBL={operating:'Operating',under_construction:'Under construction',proposed:'Proposed'};
  return H('What data-center activity is there?')+`<div class="box"><b>${num(list.length)}</b> project${list.length===1?'':'s'} tracked${list.length?': '+Object.entries(list.reduce((a,s)=>{a[s.status]=(a[s.status]||0)+1;return a;},{})).map(([k,v])=>v+' '+(LBL[k]||k).toLowerCase()).join(', '):''}${V[f].dcMW?'; <b>'+num(V[f].dcMW)+' MW</b> announced where reported':''}.<br><b>Water context:</b> ${aqList(f)}; rain last 12 months ${V[f].rainPct!=null?V[f].rainPct+'% of usual':'—'}.</div>`
    +(list.length?list.map(s=>`<div class="org"><b>${esc(s.name)}</b>${s.hot?' <small style="color:var(--hot)">flagged</small>':''}<br><small>${esc(s.operator||'operator not listed')} · ${esc(LBL[s.status]||s.status)} · ${esc(s.city||'')}${s.mw?' · '+num(s.mw)+' MW':''}${s.acres?' · '+num(s.acres)+' acres':''}${s.news?' · '+num(s.news)+' news item'+(s.news===1?'':'s'):''}${s.precision&&s.precision!=='site'?' · location: '+esc(s.precision):''}</small></div>`).join(''):'<div class="ccnote">No data center project tracked in this county.</div>')
    +`<div class="acts"><button type="button" data-layer="pins">${CM.state.pins?'Hide':'Show'} project dots on the map</button><a href="texas_data_center_map.html" target="_blank" rel="noopener">Data center map ↗</a></div>`
    +incHTML+`<div class="ccnote">Projects: Texas Data Center Watch (developer, status, announced power, site, news count); each project's news links are on the data center map.</div>`;}
document.addEventListener('click',ev=>{const p=ev.target.closest('[data-pair]');if(p){ST.pair=p.dataset.pair;renderPanel();renderRibbon();return;}
  const m=ev.target.closest('[data-dmap]');if(m){ST.dmap=m.dataset.dmap;CM.setPlan(ST.dmap);renderRibbon();renderPanel();setHash();return;}
  const l=ev.target.closest('[data-layer]');if(l){const k=l.dataset.layer;const o={};o[k]=!CM.state[k];CM.setLayers(o);renderRibbon();renderPanel();setHash();return;}
  const a=ev.target.closest('[data-act]');if(a){if(a.dataset.act==='cmp')addCompare(ST.f);else if(a.dataset.act==='brief')openBrief(ST.f);else if(a.dataset.act==='back')back();return;}});
// ---- panel ----
// ---- the Texas page (home): statewide findings and ranked lists, one block per tab ----
const sumBy=fn=>F.reduce((a,f)=>{const x=fn(f);return a+(x||0);},0);const nv=v=>v!=null?' ('+num(v)+')':'';
function homeKnow(){const out=[];const st=(t,ev)=>out.push({t,ev});const mv=F.map(f=>[f,e(f,'pres_R_change_2020_2024')]).filter(x=>x[1]!=null).sort((a,b)=>b[1]-a[1]);
  st(`Voter registration ${TEXAS.reg_since_2024>=0?'grew':'fell'} ${SPCT(TEXAS.reg_since_2024)} from the 2024 election to March 2026`,[['Nov. 2022',num(S.registered_2022)],['Nov. 2024',num(S.registered_2024)],['March 2026',num(S.registered_march_2026),1],['Change since Nov. 2024',SPCT(TEXAS.reg_since_2024),1],['Since the 2022 midterm',SPCT(TEXAS.reg_since_2022)],['On the suspense list',num(S.suspense_march_2026)+' ('+PCT(S.suspense_march_2026/S.registered_march_2026)+')']]);
  st(`Midterm turnout ${S.turnout_change_2018_2022<0?'fell':'rose'} from 2018 to 2022`,[['2018',PCT(S.turnout_2018)],['2022',PCT(S.turnout_2022)],['Change',PTS(S.turnout_change_2018_2022),1],['Counties where it fell',num(F.filter(f=>(e(f,'turnout_change_2018_2022')||0)<0).length)+' of '+num(F.length)]]);
  st(`Presidential turnout ${S.turnout_change_2020_2024<0?'fell':'rose'} from 2020 to 2024`,[['2020',PCT(S.turnout_2020)],['2024',PCT(S.turnout_2024)],['Change',PTS(S.turnout_change_2020_2024),1],['Counties where it fell',num(F.filter(f=>(e(f,'turnout_change_2020_2024')||0)<0).length)+' of '+num(F.length)]]);
  st(`Trump ${S.pres_R_change_2020_2024>=0?'gained':'lost'} ground in ${num(mv.filter(x=>x[1]>0).length)} of ${num(mv.length)} counties from 2020 to 2024`,[['Texas 2020',PCT(S.pres_R_2020)],['Texas 2024',PCT(S.pres_R_2024)],['Change',PTS(S.pres_R_change_2020_2024),1],['Furthest toward Trump',cname[mv[0][0]]+' ('+PTS(mv[0][1])+')'],['Furthest toward Democrats',cname[mv[mv.length-1][0]]+' ('+PTS(mv[mv.length-1][1])+')']]);
  st(`${S.pres_margin_2024>0?'Republicans':'Democrats'} carried Texas in 2024`,[['Republican',PCT(S.pres_R_2024)+nv(S.pres_R_votes_2024)],['Democratic',PCT(S.pres_D_2024)+nv(S.pres_D_votes_2024)],['Margin',RMN(S.pres_margin_2024,2024,'pres'),1],['Counties won by Harris',num(F.filter(f=>(e(f,'pres_margin_2024')||0)<0).length)]]);
  if(S.gov_margin_2022!=null)st(`Abbott won the 2022 governor's race statewide`,[['Abbott',PCT(S.gov_R_2022)+nv(S.gov_R_votes_2022)],["O'Rourke",PCT(S.gov_D_2022)+nv(S.gov_D_votes_2022)],['Margin',RMN(S.gov_margin_2022,2022,'gov'),1],["Counties won by O'Rourke",num(F.filter(f=>(e(f,'gov_margin_2022')||0)<0).length)]]);
  const chg=F.filter(f=>(X.changed[f]||0)>0).length,full=F.filter(f=>(X.changed[f]||0)>=0.999).length;
  st(`${num(chg)} counties have residents in a differently numbered congressional district under the 2026 map`,[['Fully renumbered',num(full)],['Partly',num(chg-full)],['Unchanged',num(F.length-chg)],['Maps','PLANC2333 (2026) vs PLANC2193 (2024)']]);
  const leg=Object.keys(raceTot).filter(k=>B.offices.some(o=>o[0]===k&&o[1]==='State district')).sort((a,b)=>raceTot[b]-raceTot[a]);const legSum=leg.reduce((a,k)=>a+raceTot[k],0);
  st(`Texas donors gave ${USDK(sumBy(f=>V[f].contribR))} to Republican and ${USDK(sumBy(f=>V[f].contribD))} to Democratic candidates for state office in 2026`,[['Republican',USDK(sumBy(f=>V[f].contribR)),1],['Democratic',USDK(sumBy(f=>V[f].contribD)),1],['Itemized gifts placed in a county',num(sumBy(f=>V[f].contribN))],['Counties giving more to Democrats',num(F.filter(f=>V[f].contribD>V[f].contribR).length)]]);
  st(`State-district candidates have raised ${USDK(legSum)} in 2026`,[['Races reporting',num(leg.length)],['Raised',USDK(legSum),1],['Best-funded race',leg.length?title(leg[0])+' ('+USDK(raceTot[leg[0]])+')':'—'],['Higher-funded means',USDK(HIGH)+' and up']]);
  const oc=Object.keys(ORG).length,cc=CATS.map(ct=>[ct,(O.orgs||[]).filter(o=>o.cat===ct).length]).filter(x=>x[1]);
  st(`${num((O.orgs||[]).length)} community organizations are listed across ${num(oc)} counties`,[['Listed',num((O.orgs||[]).length),1],['Sectors',cc.map(([c,n])=>c+' ('+num(n)+')').join(', ')],['Counties with none',num(F.length-oc)]]);
  const dry=F.filter(f=>V[f].rainPct!=null&&V[f].rainPct<80).length,dcC=Object.keys(DCC).length;
  st(`${num(dry)} counties had a dry year and ${num(dcC)} have data center projects`,[['Rain under 80% of usual',num(dry)+' counties',dry?1:0],['Data center projects',num(sumBy(f=>V[f].dcN))+' in '+num(dcC)+' counties'],['Announced power',num(Math.round(sumBy(f=>V[f].dcMW)))+' MW'],['Wells drilled since 2020',num(sumBy(f=>V[f].wellsNew))]]);
  return out;}
const rowsTX=rows=>`<table class="cmp"><tr><th>Measure</th><th>Texas</th></tr>${rows.map(([lab,fn,fmt])=>{const v=fn('48');return `<tr><td>${lab}</td><td class="me">${v==null||(typeof v==='number'&&isNaN(v))?'—':fmt(v)}</td></tr>`;}).join('')}</table>`;
const topList=(t,n,fn,fmt,sub,desc=true)=>{const l=F.map(f=>[f,fn(f)]).filter(x=>x[1]!=null&&!isNaN(x[1])).sort((a,b)=>desc?b[1]-a[1]:a[1]-b[1]).slice(0,n);return H(t)+l.map(([f,v])=>CM.countyRow(f,fmt(v),sub?sub(f):'')).join('');};
function homeOverview(){return H('Who lives in Texas?')+rowsTX(ROWS)+`<div class="ccnote">Click a county on the map or search above for its page; every county table shows the Texas figure alongside.</div>`;}
function homeElections(){const rows=[];[2024,2020,2016,2012,2008].forEach(y=>{if(S['pres_R_'+y]!=null)rows.push([y,'President',PCT(S['pres_R_'+y]),PCT(S['pres_D_'+y]),RMN(S['pres_margin_'+y],y,'pres'),PCT(S['turnout_'+y])]);});[2022,2018,2014,2010,2006].forEach(y=>{if(S['gov_R_'+y]!=null)rows.push([y,'Governor',PCT(S['gov_R_'+y]),PCT(S['gov_D_'+y]),RMN(S['gov_margin_'+y],y,'gov'),PCT(S['turnout_'+y])]);});[2024,2020,2018,2014,2012,2008,2006].forEach(y=>{if(S['sen_R_'+y]!=null)rows.push([y,'U.S. Senate',PCT(S['sen_R_'+y]),PCT(S['sen_D_'+y]),RMN(S['sen_margin_'+y],y,'sen'),PCT(S['turnout_'+y])]);});rows.sort((a,b)=>b[0]-a[0]);
  return H('How politically active is Texas, and how has it voted?')+`<table class="cmp"><tr><th style="text-align:left">Year</th><th style="text-align:left">Race</th><th>Rep.</th><th>Dem.</th><th>Margin</th><th>Turnout</th></tr>${rows.map(r=>`<tr>${r.map((c,i)=>`<td${i<2?' style="text-align:left"':''}>${c}</td>`).join('')}</tr>`).join('')}</table>`
    +topList('Fastest toward Trump, 2020 to 2024',10,f=>e(f,'pres_R_change_2020_2024'),PTS)+topList('Fastest toward Democrats, 2020 to 2024',10,f=>e(f,'pres_R_change_2020_2024'),PTS,null,false)
    +topList('Biggest midterm turnout drops, 2018 to 2022',10,f=>e(f,'turnout_change_2018_2022'),PTS,null,false)+topList('Fastest registration growth, Nov. 2024 to March 2026',10,f=>e(f,'registration_growth_2024_2026'),SPCT)+topList('Largest suspense-list share, March 2026',10,f=>V[f].suspShare,PCT)+topList('Fastest registration growth since the 2022 midterm',10,f=>V[f].regSince22,SPCT)
    +`<div class="ccnote">Turnout = top-race votes / registered voters. SOS canvass 2006-2018; TLC county subtotals 2020-2024.</div>`;}
function homeMoney(){const races=Object.entries(raceTot).sort((a,b)=>b[1]-a[1]).slice(0,15);const lvl=k=>(B.offices.find(o=>o[0]===k)||[])[1]||'';
  return H('Where is campaign money flowing?')+`<div class="box"><b>${USDK(Object.values(raceTot).reduce((a,b)=>a+b,0))}</b> raised in 2026 by candidates in ${num(Object.keys(raceTot).length)} state-district, judicial-district and district-attorney races (TEC). A race counts as higher-funded at ${USDK(HIGH)} and up (top quarter of State House, Senate and SBOE races).</div>`
    +`<div class="cat">Best-funded down-ballot races</div>`+races.map(([k,v],i)=>`<div class="org"><small>#${i+1}</small> <b>${esc(title(k))}</b> <small>· ${esc(lvl(k))}</small><br>${USD(v)} raised in 2026 by ${num(B.cands.filter(c=>B.offices[c[1]][0]===k&&c[3]!=null).length)} candidates</div>`).join('')
    +topList('Counties whose donors gave the most to Republican candidates',10,f=>V[f].contribR,USDK,f=>USDK(V[f].contribD)+' to Democrats')+topList('Counties whose donors gave the most to Democratic candidates',10,f=>V[f].contribD,USDK,f=>USDK(V[f].contribR)+' to Republicans')+topList('Counties with the most down-ballot money on the ballot',10,f=>V[f].money,USDK)+`<div class="ccnote">A district race counts in full for every county it touches. Statewide candidates are on the Ballot tab.</div>`;}
function homeBallot(){const byOff={};const order=[];B.cands.forEach(cd=>{const o=B.offices[cd[1]];if(o[1]!=='Statewide'&&o[0]!=='U. S. SENATOR')return;if(!byOff[o[0]]){byOff[o[0]]=[];order.push(o[0]);}byOff[o[0]].push(cd);});
  return H('What is on the 2026 statewide ballot?')+`<div class="box"><b>${num(order.length)}</b> statewide and U.S. Senate races with <b>${num(order.reduce((a,k)=>a+byOff[k].length,0))}</b> candidates. Open a county for its full ballot: U.S. House, legislative, judicial, district attorney, county and precinct races, and the Democratic county chair.</div>`
    +order.map(k=>{const cs=byOff[k].slice().sort((a,b)=>(b[3]||0)-(a[3]||0));return `<div class="race"><b>${esc(title(k))}</b> <small>· ${USDK(cs.reduce((a,x)=>a+(x[3]||0),0))} raised</small></div>`+cs.map((cd,i)=>candRow(cd,i,cs.length)).join('');}).join('')
    +`<div class="ccnote">SOS certification of ${esc(B.ballot_cert)}; ${esc(B.fund_asof)}; FEC 2025-26 cycle totals for federal candidates.</div>`;}
function homeCommunity(){const cc=CATS.map(ct=>[ct,(O.orgs||[]).filter(o=>o.cat===ct)]).filter(x=>x[1].length);
  return H('Which organizations are present, statewide?')+`<table class="cmp"><tr><th style="text-align:left">Sector</th><th>Organizations</th><th>Counties</th></tr>${cc.map(([ct,l])=>`<tr><td>${esc(ct)}</td><td>${num(l.length)}</td><td>${num(new Set(l.map(o=>o.f)).size)}</td></tr>`).join('')}</table>`
    +topList('Counties with the most organizations listed',10,f=>V[f].orgs,num)+`<div class="ccnote">${esc(O.caution||'An organization does not control or perfectly represent its members.')}</div>`;}
function homeDistricts(){const plan=ST.dmap;const yr=R[plan]&&R[plan].years[2024];if(!yr)return '';const ds=Object.keys(yr.d).map(n=>[+n,marg(plan,2024,'pres',n)]).filter(x=>x[1]!=null);const close=ds.slice().sort((a,b)=>Math.abs(a[1])-Math.abs(b[1])).slice(0,10);const dem=ds.filter(x=>x[1]<0).length;
  return H('What changed because of redistricting?')
    +`<div class="box">${esc((CM.plan(plan)||{}).label||plan)}: <b>${num(ds.length)}</b> districts. On the 2024 presidential vote ${num(dem)} lean Democratic and ${num(ds.length-dem)} Republican; ${num(ds.filter(x=>Math.abs(x[1])<0.1).length)} are within 10 points.</div>`
    +H('Closest districts, 2024 presidential vote')+close.map(([n,m])=>CM.districtRow(plan,n,RM(m),'')).join('')
    +topList('Counties with the most residents in a new district number',10,f=>X.changed[f],PCT0)+`<div class="ccnote">${esc((R[plan]||{}).basis||'')}.</div>`;}
function homeWater(){return H('What water and aquifer context matters?')+topList('Driest counties, last 12 months vs. usual',10,f=>V[f].rainPct,v=>v+'% of usual',null,false)+topList('Most wells drilled since 2020',10,f=>V[f].wellsNew,num)+`<div class="ccnote">Rain: PRISM county means. Wells: TWDB driller reports. Aquifers are on each county's Water tab.</div>`;}
function homeDC(){const n=sumBy(f=>V[f].dcN),mw=sumBy(f=>V[f].dcMW),st=INC.state||{};return H('What data-center activity is there?')+`<div class="box"><b>${num(n)}</b> projects tracked in ${num(Object.keys(DCC).length)} counties; ${num(Math.round(mw))} MW announced where reported. The Data centers coloring shows the projects as dots.</div>`+(st.deals_n?`<div class="box"><b>${num(st.deals_n)}</b> local incentive deals recorded in ${num(st.deals_placed_counties)} counties (${Object.entries(st.by_program||{}).sort((a,b)=>b[1]-a[1]).map(([p,k])=>esc(p)+' '+num(k)).join(', ')}); ERCOT queue ${num(st.queued_mw)} MW in ${num(st.burden_counties)} counties; <b>${num(st.links_n)}</b> data-center projects in ${num(st.links_counties)} counties linked to Abbott donors (${USDK(st.links_lifetime)} lifetime giving).</div>`+topList('Counties with the most reported incentive value',10,f=>V[f].incValue,USDK)+topList('Largest ERCOT queue (MW)',10,f=>V[f].queuedMW,num)+topList('Abbott giving linked to data-center projects',10,f=>V[f].dcLinkTotal,USDK):'')+topList('Counties with the most projects',10,f=>V[f].dcN,num,f=>V[f].dcMW?num(Math.round(V[f].dcMW))+' MW announced':'')+`<div class="ccnote">Texas Data Center Watch; withdrawn projects excluded.</div>`;}
function renderHome(){const tab={overview:homeOverview,elections:homeElections,money:homeMoney,ballot:homeBallot,community:homeCommunity,districts:homeDistricts,water:homeWater,dc:homeDC}[ST.tab]||homeOverview;
  side.innerHTML=`<div class="detail"><h2>Texas</h2><div class="sub">${num(F.length)} counties · ${num(TXD['Population, July 1 2025 (TDC prelim.)'])} people · ${num(S.registered_march_2026)} registered (March 2026) · 38 congressional districts</div>${ST.tab==='overview'?knowBlock(homeKnow()):''}<div class="cctab">${tab()}</div></div>`;}
function renderPanel(){if(!ST.f){renderHome();return;}
  const f=ST.f;const tab={overview:tabOverview,elections:tabElections,money:tabMoney,ballot:tabBallot,community:tabCommunity,districts:tabDistricts,water:tabWater,dc:tabDC}[ST.tab]||tabOverview;
  side.innerHTML=`<div class="detail"><button class="back" data-act="back">← Texas</button><h2>${esc(cname[f])} County</h2><div class="sub">${esc((RG[f]||{}).Region||'')} · ${num(d(f,'Population, July 1 2025 (TDC prelim.)'))} people · ${num(e(f,'registered_march_2026'))} registered (March 2026) · ${((X.counties[f]||{})[NEW]||[]).map(([n])=>'CD '+n).join(', ')} (2026 map)${ST.place?' · searched: '+esc(ST.place):''}</div>
    <div class="acts phone"><button type="button" data-act="cmp"${ST.cmp.includes(f)||ST.cmp.length>=3?' disabled':''}>${ST.cmp.includes(f)?'In the compare tray':'+ Add to compare'}</button><button type="button" class="primary" data-act="brief">Prepare roundtable</button></div>${ST.tab==='overview'?knowHTML(f):`<details class="knowfold"><summary>What to know · ${know(f).length} findings</summary>${knowHTML(f)}</details>`}<div class="cctab">${tab(f)}</div></div>`;}
function showCounty(f){if(!DM[f])return;ST.f=f;$('sb-cur').textContent=cname[f]+' County';$('side-title').textContent=cname[f]+' County';CM.select(null);CM.highlightDistrict(null);CM.highlightCounty(f);CM.zoomCounty(f);renderPanel();renderTray();setHash();}
function back(){ST.f='';ST.place='';$('sb-cur').textContent='Move over the map to read a county';$('side-title').textContent='Texas';renderRibbon();CM.highlightCounty(null);CM.highlightDistrict(null);CM.fit();renderPanel();renderTray();setHash();}
function showDistrict(plan,n){const cs=CM.districtCounties(plan,n);if(CM.activePlan()!==plan)CM.setPlan(plan);CM.highlightDistrict(plan,n);CM.zoomDistrict(plan,n);renderRibbon();
  const rows=[];Object.keys(R[plan]?R[plan].years:{}).map(Number).sort((a,b)=>b-a).forEach(y=>{const r=dres(plan,y,n);if(!r)return;[['pres','President'],['gov','Governor'],['sen','U.S. Senate']].forEach(([k,lab])=>{if(!r[k])return;const nm=names(plan,y,k);rows.push([y,lab,esc(nm[0])+' '+PCT(r[k][0]),esc(nm[1])+' '+PCT(r[k][1]),RM(r[k][0]-r[k][1]),r.vr!=null?num(r.vr):'—',r.bal!=null?num(r.bal):'—']);});});
  side.innerHTML=`<div class="detail"><button class="back" id="dback">← Back</button><span class="status">${esc((CM.plan(plan)||{}).label||plan)}</span><h2>${esc(CM.districtName(plan,n))}</h2><div class="sub">${cs.length} ${cs.length===1?'county':'counties'}</div><div class="cctab">${H('How this district voted')}<table class="cmp"><tr><th>Year</th><th>Race</th><th>Rep.</th><th>Dem.</th><th>Margin</th><th>Registered</th><th>Ballots</th></tr>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</table><div class="ccnote">${esc((R[plan]||{}).basis||'')}.</div>${H('Counties in this district')}${cs.map(c=>CM.countyRow(c[0],PCT0(c[2]),c[2]<0.995?'part of the county':'')).join('')}</div></div>`;
  $('dback').onclick=()=>{CM.highlightDistrict(null);if(ST.f)showCounty(ST.f);else back();};}
// ---- an aquifer card: which counties lie over it and which data centers sit on top ----
function showAquifer(name,kind){const a=CM.aquifer(name);if(!a)return;kind=kind||a.kind;if(!CM.state.aquifers)CM.setLayers({aquifers:true});CM.highlightAquifer(name);CM.zoomAquifer(name);
  const cs=F.map(f=>{const x=((AQ[f]||{}).aq||[]).find(q=>q[0]===name);return x?[f,x[2]]:null;}).filter(Boolean).sort((a,b)=>b[1]-a[1]);CM.highlightCounties(cs.map(x=>x[0]));
  const pins=CM.pinsInAquifer(name).sort((a,b)=>(b.size||0)-(a.size||0));const mw=pins.reduce((t,p)=>t+(p.size||0),0);if(pins.length&&!CM.state.pins)CM.setLayers({pins:true});const st={};pins.forEach(p=>st[p.status]=(st[p.status]||0)+1);
  const mostly=cs.filter(x=>x[1]>=0.5);const wells=mostly.reduce((t,[f])=>t+(V[f].wellsNew||0),0),reg=mostly.reduce((t,[f])=>t+(e(f,'registered_march_2026')||0),0),pop=mostly.reduce((t,[f])=>t+(d(f,'Population, July 1 2025 (TDC prelim.)')||0),0);
  $('side-title').textContent=name+' aquifer';renderRibbon();
  side.innerHTML=`<div class="detail"><button class="back" id="aqback">← Back</button><span class="status">${kind==='minor'?'Minor':'Major'} aquifer (TWDB outline)</span><h2>${esc(name)}</h2><div class="sub">${num(cs.length)} counties lie at least partly over it · ${num(pins.length)} data center project${pins.length===1?'':'s'} on top${mw?' · '+num(Math.round(mw))+' MW announced where reported':''}</div>
    <div class="cctab">${H('Data centers on top of this aquifer')}${pins.length?`<div class="box">${Object.entries(st).map(([k,v])=>num(v)+' '+k.replace('_',' ')).join(', ')}. A project counts when its site coordinates fall inside the aquifer outline.</div>`+pins.map(p=>`<div class="org"><b>${esc(p.name)}</b>${p.hot?' <small style="color:var(--hot)">flagged</small>':''}<br><small>${esc(cname[p.fips]||p.county||'')} County · ${esc(p.sub||'operator not listed')} · ${esc(String(p.status).replace('_',' '))}${p.size?' · '+num(p.size)+' MW':''}${p.city?' · '+esc(p.city):''}</small></div>`).join(''):'<div class="ccnote">No tracked data center project has its site over this aquifer.</div>'}
    ${H('Counties over this aquifer')}<div class="box">${num(mostly.length)} counties are mostly (50%+) over it: ${num(pop)} people, ${num(reg)} registered voters (March 2026), ${num(wells)} wells drilled since 2020.</div><div class="ccnote">Share of each county's area over the aquifer (grid sampling of the TWDB outline); click a county to open its page.</div>${cs.map(([f,sh])=>CM.countyRow(f,PCT0(sh),(DCC[f]||[]).length?num((DCC[f]||[]).length)+' data center project'+((DCC[f]||[]).length===1?'':'s'):'')).join('')}
    <div class="ccnote">TWDB major and minor aquifer outlines (generalized); Texas Data Center Watch sites placed by their coordinates; county shares from tx_county_aquifers.js. Click an aquifer name on the map or in the Contents pane to open another.</div></div></div>`;
  $('aqback').onclick=()=>{CM.highlightAquifer(null);CM.highlightCounties([]);if(ST.f)showCounty(ST.f);else back();};CM.setHash('aquifer='+encodeURIComponent(name)+(CM.state.base?'&color='+CM.state.base:''));}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-aq]');if(b){showAquifer(b.dataset.aq);return;}const r=ev.target.closest('#contents .lyr .r');if(r){const cb=r.closest('.lyr').querySelector('[data-lyr]');if(cb&&cb.dataset.lyr==='aquifers')showAquifer(r.textContent.trim());}});
